-- =============================================================================
-- 066 — Marathi (mr) and Kannada (kn) versions of the guides.
--
-- WHY (owner, 2026-10-06): ForKhatri adds Marathi and Kannada alongside
-- English, Hindi and Telugu. Each guide's `content` gains "mr" and "kn"
-- entries; `content || jsonb` adds those two keys only, so the existing
-- en/hi/te text is left exactly as it is. The same text is in
-- mangaly-service/app/components/guides/content.json.
-- No schema change. Idempotent: re-running writes the same two keys again.
-- =============================================================================

UPDATE mangaly_content.guide
   SET content = content || $guide${"mr": {"title": "Mangalya कसे काम करते, टप्प्याटप्प्याने", "summary": "प्रोफाइल बनवण्यापासून पहिल्या संवादापर्यंत, जसे घडते त्याच क्रमाने.", "sections": [{"p": "Mangalya कुटुंबांसाठी बनवले आहे. उमेदवार स्वतःही शोध घेऊ शकतात, आणि आई-वडील, भाऊ-बहीण किंवा पालक आपापल्या फोनवरून मदत करू शकतात."}, {"h": "टप्पे", "points": ["प्रोफाइल बनवा: थोडी माहिती, एक स्पष्ट फोटो, आणि तुम्ही कोणाला शोधत आहात ते.", "‘शोधा’ मध्ये स्थळे पाहा. दोन्ही बाजूंच्या अपेक्षांचा आदर केला जातो: ज्यांच्या अपेक्षांमध्ये तुम्ही बसता, तेच लोक तुम्हाला दिसतात.", "जे स्थळ योग्य वाटेल, त्यांना विनंती पाठवा. त्यांचे कुटुंब ती पाहून निर्णय घेते.", "त्यांनी स्वीकारल्यावर तुम्ही दोघे एका खासगी संवादात बोलू शकता, ज्यात काहीही जतन होत नाही, आणि दोन्ही कुटुंबे कुटुंब-संवादात बोलू शकतात.", "दोन्ही कुटुंबे तयार असतील तेव्हा भेटा. त्यानंतर ‘लग्नाची तयारी’ पुढच्या कामांत मदत करते."]}, {"p": "तुमच्या अपेक्षांबाहेरील लोकांना तुम्ही कधीही दाखवले जात नाही, आणि Mangalya मध्ये कुठेही स्क्रीनशॉट घेता येत नाही."}]}, "kn": {"title": "Mangalya ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ, ಹಂತ ಹಂತವಾಗಿ", "summary": "ನಿಮ್ಮ ಪ್ರೊಫೈಲ್‌ನಿಂದ ಮೊದಲ ಸಂಭಾಷಣೆಯವರೆಗೆ, ಅದು ನಡೆಯುವ ಕ್ರಮದಲ್ಲೇ.", "sections": [{"p": "Mangalya ಕುಟುಂಬಗಳಿಗಾಗಿ ಮಾಡಲಾಗಿದೆ. ಅಭ್ಯರ್ಥಿಗಳು ತಾವೇ ಹುಡುಕಬಹುದು, ಮತ್ತು ತಂದೆ-ತಾಯಿ, ಸಹೋದರ-ಸಹೋದರಿಯರು ಅಥವಾ ಪಾಲಕರು ತಮ್ಮ ತಮ್ಮ ಫೋನ್‌ನಿಂದ ಸಹಾಯ ಮಾಡಬಹುದು."}, {"h": "ಹಂತಗಳು", "points": ["ಪ್ರೊಫೈಲ್ ಮಾಡಿ: ಕೆಲವು ವಿವರಗಳು, ಒಂದು ಸ್ಪಷ್ಟ ಫೋಟೋ, ಮತ್ತು ನೀವು ಯಾರನ್ನು ಹುಡುಕುತ್ತಿದ್ದೀರಿ ಎಂಬುದು.", "‘ಹುಡುಕಿ’ಯಲ್ಲಿ ಸಂಬಂಧಗಳನ್ನು ನೋಡಿ. ಎರಡೂ ಕಡೆಯ ಆಶಯಗಳನ್ನು ಗೌರವಿಸಲಾಗುತ್ತದೆ: ಯಾರ ಆಶಯಗಳಲ್ಲಿ ನೀವೂ ಸೇರುತ್ತೀರೋ, ಅವರು ಮಾತ್ರ ನಿಮಗೆ ಕಾಣಿಸುತ್ತಾರೆ.", "ಸರಿ ಅನ್ನಿಸುವವರಿಗೆ ವಿನಂತಿ ಕಳುಹಿಸಿ. ಅವರ ಕುಟುಂಬ ಅದನ್ನು ನೋಡಿ ನಿರ್ಧರಿಸುತ್ತದೆ.", "ಅವರು ಒಪ್ಪಿದಾಗ, ನೀವಿಬ್ಬರೂ ಏನನ್ನೂ ಉಳಿಸಿಡದ ಖಾಸಗಿ ಸಂಭಾಷಣೆಯಲ್ಲಿ ಮಾತನಾಡಬಹುದು, ಮತ್ತು ಎರಡೂ ಕುಟುಂಬಗಳು ಕುಟುಂಬ ಸಂಭಾಷಣೆಯಲ್ಲಿ ಮಾತನಾಡಬಹುದು.", "ಎರಡೂ ಕುಟುಂಬಗಳು ಸಿದ್ಧವಾದಾಗ ಭೇಟಿಯಾಗಿ. ನಂತರ ‘ಮದುವೆ ಸಿದ್ಧತೆಗಳು’ ಮುಂದಿನ ಹಂತಗಳಿಗೆ ಸಹಾಯ ಮಾಡುತ್ತದೆ."]}, {"p": "ನಿಮ್ಮ ಆಶಯಗಳ ಹೊರಗಿನವರಿಗೆ ನಿಮ್ಮನ್ನು ಎಂದಿಗೂ ತೋರಿಸಲಾಗುವುದಿಲ್ಲ, ಮತ್ತು Mangalya ಒಳಗೆ ಎಲ್ಲಿಯೂ ಸ್ಕ್ರೀನ್‌ಶಾಟ್ ತೆಗೆಯಲು ಆಗುವುದಿಲ್ಲ."}]}}$guide$::jsonb, updated_at = now()
 WHERE slug = 'how-mangalya-works';

UPDATE mangaly_content.guide
   SET content = content || $guide${"mr": {"title": "तुमच्या कुटुंबाला शोधात सामील करा", "summary": "Home Circle मुळे आई-वडील आणि कुटुंबीय आपापल्या फोनवरून मदत करू शकतात.", "sections": [{"p": "Home Circle म्हणजे तुमच्या शोधात मदत करणारा कुटुंबाचा छोटा गट: आई किंवा वडील, भाऊ किंवा बहीण, घरातील वडीलधारी व्यक्ती, किंवा पालक."}, {"h": "एखाद्याला कसे जोडावे", "points": ["मेनूमधून ‘सर्कल’ उघडा.", "नाव किंवा मोबाइल नंबरने त्यांना शोधा आणि ते तुमचे कोण लागतात ते निवडा.", "ते त्यांच्या स्वतःच्या नंबरने, त्यांना सगळ्यात चांगली वाचता येणाऱ्या भाषेत सामील होतात."]}, {"h": "ते काय करू शकतात", "points": ["तुमची स्थळे पाहणे आणि आवडलेली स्थळे जतन करणे.", "तुमच्या वतीने विनंत्या पाठवणे, आणि आलेल्या विनंत्या स्वीकारणे किंवा नाकारणे.", "कुटुंब-संवादात दुसऱ्या कुटुंबाशी बोलणे."]}, {"p": "स्थळासोबतचा तुमचा खासगी संवाद फक्त तुमचाच राहतो. कुटुंब तो कधीही वाचत नाही."}]}, "kn": {"title": "ನಿಮ್ಮ ಕುಟುಂಬವನ್ನು ಹುಡುಕಾಟದಲ್ಲಿ ಸೇರಿಸಿಕೊಳ್ಳಿ", "summary": "Home Circle ಮೂಲಕ ತಂದೆ-ತಾಯಿ ಮತ್ತು ಕುಟುಂಬದವರು ತಮ್ಮ ತಮ್ಮ ಫೋನ್‌ನಿಂದ ಸಹಾಯ ಮಾಡಬಹುದು.", "sections": [{"p": "Home Circle ಎಂದರೆ ನಿಮ್ಮ ಹುಡುಕಾಟದಲ್ಲಿ ಸಹಾಯ ಮಾಡುವ ಕುಟುಂಬದ ಸಣ್ಣ ಗುಂಪು: ತಂದೆ ಅಥವಾ ತಾಯಿ, ಸಹೋದರ ಅಥವಾ ಸಹೋದರಿ, ಮನೆಯ ಹಿರಿಯರು, ಅಥವಾ ಪಾಲಕರು."}, {"h": "ಯಾರನ್ನಾದರೂ ಸೇರಿಸುವುದು ಹೇಗೆ", "points": ["ಮೆನುವಿನಿಂದ ‘ಸರ್ಕಲ್’ ತೆರೆಯಿರಿ.", "ಹೆಸರು ಅಥವಾ ಮೊಬೈಲ್ ಸಂಖ್ಯೆಯಿಂದ ಅವರನ್ನು ಹುಡುಕಿ, ಮತ್ತು ಅವರು ನಿಮಗೆ ಏನಾಗಬೇಕು ಎಂಬುದನ್ನು ಆಯ್ಕೆಮಾಡಿ.", "ಅವರು ತಮ್ಮದೇ ಸಂಖ್ಯೆಯಿಂದ, ತಮಗೆ ಚೆನ್ನಾಗಿ ಓದಲು ಬರುವ ಭಾಷೆಯಲ್ಲಿ ಸೇರುತ್ತಾರೆ."]}, {"h": "ಅವರು ಏನು ಮಾಡಬಹುದು", "points": ["ನಿಮ್ಮ ಸಂಬಂಧಗಳನ್ನು ನೋಡುವುದು ಮತ್ತು ಇಷ್ಟವಾದವುಗಳನ್ನು ಉಳಿಸುವುದು.", "ನಿಮ್ಮ ಪರವಾಗಿ ವಿನಂತಿಗಳನ್ನು ಕಳುಹಿಸುವುದು, ಮತ್ತು ಬಂದ ವಿನಂತಿಗಳನ್ನು ಒಪ್ಪುವುದು ಅಥವಾ ನಿರಾಕರಿಸುವುದು.", "ಕುಟುಂಬ ಸಂಭಾಷಣೆಯಲ್ಲಿ ಇನ್ನೊಂದು ಕುಟುಂಬದೊಂದಿಗೆ ಮಾತನಾಡುವುದು."]}, {"p": "ಸಂಬಂಧದೊಂದಿಗಿನ ನಿಮ್ಮ ಖಾಸಗಿ ಸಂಭಾಷಣೆ ನಿಮ್ಮದು ಮಾತ್ರ. ಕುಟುಂಬದವರು ಅದನ್ನು ಎಂದಿಗೂ ಓದುವುದಿಲ್ಲ."}]}}$guide$::jsonb, updated_at = now()
 WHERE slug = 'bring-your-family';

UPDATE mangaly_content.guide
   SET content = content || $guide${"mr": {"title": "कुटुंबांना विश्वास वाटेल असे प्रोफाइल", "summary": "दुसरे कुटुंब कशामुळे थांबते, वाचते आणि विनंती पाठवते.", "sections": [{"p": "एखादा नातेवाईक कोणाबद्दल सांगत असताना जसे ऐकतात, तसेच कुटुंबे प्रोफाइल वाचतात. लांबलचक स्तुतीपेक्षा साधी, खरी माहिती जास्त महत्त्वाची असते."}, {"h": "हे करा", "points": ["शिक्षण, काम, कुटुंब आणि तुम्ही काय शोधत आहात ते भरा. रिकामे भाग पाहून कुटुंबांना प्रश्न पडतो.", "दोन-तीन प्रश्नांची उत्तरे तुमच्या स्वतःच्या शब्दांत द्या: तुम्ही रविवार कसा घालवता, तुमच्यासाठी घर म्हणजे काय.", "वैवाहिक पार्श्वभूमी, आहार आणि स्थलांतराची तयारी याबद्दल खरे सांगा. त्यामुळे दोन्ही कुटुंबांचा वेळ वाचतो.", "तुमचा चेहरा पडताळून घ्या. बहुतेक कुटुंबे सगळ्यात आधी पडताळणीचे चिन्ह पाहतात."]}, {"h": "हे टाळा", "points": ["अपेक्षांची यादी (\"गोरी हवी, इतके कमावणारा हवा…\"). त्यामुळे चांगली कुटुंबे दूर जातात.", "इतर प्रोफाइलमधील ओळी कॉपी करणे. कुटुंबांच्या ते लगेच लक्षात येते."]}]}, "kn": {"title": "ಕುಟುಂಬಗಳು ನಂಬುವ ಪ್ರೊಫೈಲ್", "summary": "ಇನ್ನೊಂದು ಕುಟುಂಬ ನಿಂತು, ಓದಿ, ವಿನಂತಿ ಕಳುಹಿಸುವಂತೆ ಮಾಡುವುದು ಯಾವುದು.", "sections": [{"p": "ಸಂಬಂಧಿಕರೊಬ್ಬರು ಯಾರ ಬಗ್ಗೆಯಾದರೂ ಹೇಳುವುದನ್ನು ಕೇಳುವಂತೆಯೇ ಕುಟುಂಬಗಳು ಪ್ರೊಫೈಲ್ ಓದುತ್ತವೆ. ಉದ್ದುದ್ದ ಹೊಗಳಿಕೆಗಿಂತ ಸರಳ, ಸತ್ಯವಾದ ವಿವರಗಳೇ ಮುಖ್ಯ."}, {"h": "ಇವುಗಳನ್ನು ಮಾಡಿ", "points": ["ಶಿಕ್ಷಣ, ಕೆಲಸ, ಕುಟುಂಬ ಮತ್ತು ನೀವು ಏನನ್ನು ಹುಡುಕುತ್ತಿದ್ದೀರಿ ಎಂಬುದನ್ನು ತುಂಬಿ. ಖಾಲಿ ಭಾಗಗಳನ್ನು ನೋಡಿದರೆ ಕುಟುಂಬಗಳಿಗೆ ಅನುಮಾನ ಬರುತ್ತದೆ.", "ಎರಡು-ಮೂರು ಪ್ರಶ್ನೆಗಳಿಗೆ ನಿಮ್ಮದೇ ಮಾತುಗಳಲ್ಲಿ ಉತ್ತರಿಸಿ: ನೀವು ಭಾನುವಾರವನ್ನು ಹೇಗೆ ಕಳೆಯುತ್ತೀರಿ, ನಿಮಗೆ ಮನೆ ಎಂದರೆ ಏನು.", "ವೈವಾಹಿಕ ಹಿನ್ನೆಲೆ, ಆಹಾರ ಪದ್ಧತಿ ಮತ್ತು ಬೇರೆ ಊರಿಗೆ ಹೋಗುವ ಸಿದ್ಧತೆಯ ಬಗ್ಗೆ ಪ್ರಾಮಾಣಿಕವಾಗಿ ಹೇಳಿ. ಇದರಿಂದ ಎರಡೂ ಕುಟುಂಬಗಳ ಸಮಯ ಉಳಿಯುತ್ತದೆ.", "ನಿಮ್ಮ ಮುಖವನ್ನು ಪರಿಶೀಲಿಸಿಕೊಳ್ಳಿ. ಹೆಚ್ಚಿನ ಕುಟುಂಬಗಳು ಮೊದಲು ನೋಡುವುದೇ ಪರಿಶೀಲನೆಯ ಗುರುತನ್ನು."]}, {"h": "ಇವುಗಳನ್ನು ತಪ್ಪಿಸಿ", "points": ["ಬೇಡಿಕೆಗಳ ಪಟ್ಟಿ (\"ಬೆಳ್ಳಗಿರಬೇಕು, ಇಷ್ಟು ಸಂಪಾದಿಸಬೇಕು…\"). ಇದರಿಂದ ಒಳ್ಳೆಯ ಕುಟುಂಬಗಳು ದೂರ ಸರಿಯುತ್ತವೆ.", "ಬೇರೆ ಪ್ರೊಫೈಲ್‌ಗಳ ಸಾಲುಗಳನ್ನು ನಕಲು ಮಾಡುವುದು. ಕುಟುಂಬಗಳು ಅದನ್ನು ಗುರುತಿಸುತ್ತವೆ."]}]}}$guide$::jsonb, updated_at = now()
 WHERE slug = 'a-profile-families-trust';

UPDATE mangaly_content.guide
   SET content = content || $guide${"mr": {"title": "घरीच काढलेले चांगले फोटो", "summary": "एक फोन आणि एक खिडकी पुरेशी आहे. स्टुडिओची गरज नाही.", "sections": [{"p": "तुमचा पहिला फोटो पाहूनच कुटुंब तुमचे प्रोफाइल उघडायचे की नाही ते ठरवते. त्यात तुमचा चेहरा स्पष्ट दिसावा आणि तुम्ही आज जसे दिसता तसेच दिसावे."}, {"h": "पाच सोपे नियम", "points": ["दिवसाच्या उजेडात खिडकीकडे तोंड करून उभे राहा. खिडकी कधीही तुमच्या मागे नको.", "कोणाला तरी फोन तुमच्या डोळ्यांच्या उंचीवर, साधारण दोन हातांच्या अंतरावर धरायला सांगा.", "फोटोचा बहुतेक भाग चेहरा आणि खांद्यांनी भरलेला असावा. सहज हसा.", "मागे साधी भिंत किंवा नीटनेटकी खोली असावी. गर्दी नको, दुसऱ्या कोणाला कापून काढलेले फोटो नकोत.", "फिल्टर, गॉगल किंवा जास्त एडिटिंग नको. कुटुंबांना खरी व्यक्ती पाहायची असते."]}, {"h": "आणखी काही जोडा", "points": ["कौटुंबिक कार्यक्रमाला जे कपडे घालाल, त्यातला एक पूर्ण उंचीचा फोटो.", "तुम्हाला आवडणारे काहीतरी करताना एक फोटो: स्वयंपाक, संगीत, ट्रेक.", "सगळे फोटो गेल्या वर्षभरातले असावेत."]}]}, "kn": {"title": "ಮನೆಯಲ್ಲೇ ತೆಗೆದ ಒಳ್ಳೆಯ ಫೋಟೋಗಳು", "summary": "ಒಂದು ಫೋನ್ ಮತ್ತು ಒಂದು ಕಿಟಕಿ ಸಾಕು. ಸ್ಟುಡಿಯೋ ಬೇಕಿಲ್ಲ.", "sections": [{"p": "ನಿಮ್ಮ ಮೊದಲ ಫೋಟೋ ನೋಡಿಯೇ ಕುಟುಂಬವೊಂದು ನಿಮ್ಮ ಪ್ರೊಫೈಲ್ ತೆರೆಯಬೇಕೇ ಎಂದು ನಿರ್ಧರಿಸುತ್ತದೆ. ಅದರಲ್ಲಿ ನಿಮ್ಮ ಮುಖ ಸ್ಪಷ್ಟವಾಗಿ ಕಾಣಬೇಕು, ಮತ್ತು ನೀವು ಇಂದು ಇರುವಂತೆಯೇ ಕಾಣಬೇಕು."}, {"h": "ಐದು ಸರಳ ನಿಯಮಗಳು", "points": ["ಹಗಲಿನ ಬೆಳಕಿನಲ್ಲಿ ಕಿಟಕಿಯ ಕಡೆ ಮುಖ ಮಾಡಿ ನಿಲ್ಲಿ. ಕಿಟಕಿ ಎಂದಿಗೂ ನಿಮ್ಮ ಹಿಂದೆ ಇರಬಾರದು.", "ಯಾರಾದರೂ ಫೋನ್ ಅನ್ನು ನಿಮ್ಮ ಕಣ್ಣಿನ ಎತ್ತರದಲ್ಲಿ, ಸುಮಾರು ಎರಡು ತೋಳಿನಷ್ಟು ದೂರದಲ್ಲಿ ಹಿಡಿಯಲಿ.", "ಫೋಟೋದ ಹೆಚ್ಚಿನ ಭಾಗ ಮುಖ ಮತ್ತು ಭುಜಗಳಿಂದ ತುಂಬಿರಲಿ. ಸಹಜವಾಗಿ ನಗಿ.", "ಹಿಂದೆ ಸರಳ ಗೋಡೆ ಅಥವಾ ಅಚ್ಚುಕಟ್ಟಾದ ಕೋಣೆ ಇರಲಿ. ಜನಸಂದಣಿ ಬೇಡ, ಬೇರೆಯವರನ್ನು ಕತ್ತರಿಸಿ ತೆಗೆದ ಫೋಟೋ ಬೇಡ.", "ಫಿಲ್ಟರ್, ಕಪ್ಪು ಕನ್ನಡಕ ಅಥವಾ ಹೆಚ್ಚು ಎಡಿಟಿಂಗ್ ಬೇಡ. ಕುಟುಂಬಗಳು ನಿಜವಾದ ವ್ಯಕ್ತಿಯನ್ನು ನೋಡಲು ಬಯಸುತ್ತವೆ."]}, {"h": "ಇನ್ನೂ ಕೆಲವು ಸೇರಿಸಿ", "points": ["ಕುಟುಂಬದ ಸಮಾರಂಭಕ್ಕೆ ನೀವು ಧರಿಸುವ ಬಟ್ಟೆಯಲ್ಲಿ ಒಂದು ಪೂರ್ಣ ಎತ್ತರದ ಫೋಟೋ.", "ನಿಮಗೆ ಇಷ್ಟವಾದುದನ್ನು ಮಾಡುತ್ತಿರುವ ಒಂದು ಫೋಟೋ: ಅಡುಗೆ, ಸಂಗೀತ, ಚಾರಣ.", "ಎಲ್ಲಾ ಫೋಟೋಗಳು ಕಳೆದ ಒಂದು ವರ್ಷದೊಳಗಿನವಾಗಿರಲಿ."]}]}}$guide$::jsonb, updated_at = now()
 WHERE slug = 'good-photos-at-home';

UPDATE mangaly_content.guide
   SET content = content || $guide${"mr": {"title": "फोटोसाठी काय घालावे", "summary": "पेहरावाच्या सोप्या सूचना, ज्या कोणत्याही फोनवर छान दिसतात.", "sections": [{"h": "पहिल्या फोटोसाठी", "points": ["भडक प्रिंटपेक्षा एकाच रंगाचे कपडे चांगले दिसतात: मरून, गडद हिरवा, नेव्ही, मोहरी पिवळा, क्रीम.", "महिलांसाठी: साडी, सलवार सूट किंवा साधी कुर्ती; हलके दागिने आणि नीट विंचरलेले केस.", "पुरुषांसाठी: इस्त्री केलेला साधा शर्ट किंवा कुर्ता; ताजी दाढी केलेला चेहरा किंवा नीट कोरलेली दाढी."]}, {"h": "पारंपरिक फोटोसाठी", "points": ["चुलत-मावस भावंडाच्या साखरपुड्याला जे घालाल ते: रेशमी साडी किंवा लेहेंगा, कुर्ता किंवा शेरवानी.", "असा एकच फोटो ठेवा. तुम्ही रोज कसे दिसता, हेही कुटुंबांना पाहायचे असते."]}, {"p": "जे आरामदायक आणि तुमचे स्वतःचे आहे तेच घाला. उसना पेहराव फोटोत लगेच कळतो."}]}, "kn": {"title": "ಫೋಟೋಗಳಲ್ಲಿ ಏನು ಧರಿಸಬೇಕು", "summary": "ಯಾವುದೇ ಫೋನ್ ಪರದೆಯಲ್ಲೂ ಚೆನ್ನಾಗಿ ಕಾಣುವ ಸರಳ ಉಡುಪಿನ ಸಲಹೆಗಳು.", "sections": [{"h": "ಮೊದಲ ಫೋಟೋಗೆ", "points": ["ಗಿಜಿಗಿಜಿ ಪ್ರಿಂಟ್‌ಗಳಿಗಿಂತ ಒಂದೇ ಬಣ್ಣದ ಬಟ್ಟೆಗಳು ಚೆನ್ನಾಗಿ ಕಾಣುತ್ತವೆ: ಮರೂನ್, ಗಾಢ ಹಸಿರು, ನೇವಿ, ಸಾಸಿವೆ ಹಳದಿ, ಕ್ರೀಮ್.", "ಮಹಿಳೆಯರಿಗೆ: ಸೀರೆ, ಸಲ್ವಾರ್ ಸೂಟ್ ಅಥವಾ ಸರಳ ಕುರ್ತಿ; ಹಗುರವಾದ ಆಭರಣ ಮತ್ತು ಅಚ್ಚುಕಟ್ಟಾದ ಕೂದಲು.", "ಪುರುಷರಿಗೆ: ಇಸ್ತ್ರಿ ಮಾಡಿದ ಸರಳ ಶರ್ಟ್ ಅಥವಾ ಕುರ್ತಾ; ಹೊಸದಾಗಿ ಶೇವ್ ಮಾಡಿದ ಮುಖ ಅಥವಾ ಅಚ್ಚುಕಟ್ಟಾಗಿ ಕತ್ತರಿಸಿದ ಗಡ್ಡ."]}, {"h": "ಸಾಂಪ್ರದಾಯಿಕ ಫೋಟೋಗೆ", "points": ["ಸಂಬಂಧಿಕರ ನಿಶ್ಚಿತಾರ್ಥಕ್ಕೆ ನೀವು ಧರಿಸುವಂಥದ್ದು: ರೇಷ್ಮೆ ಸೀರೆ ಅಥವಾ ಲೆಹೆಂಗಾ, ಕುರ್ತಾ ಅಥವಾ ಶೆರ್ವಾನಿ.", "ಅಂಥದ್ದು ಒಂದೇ ಫೋಟೋ ಇರಲಿ. ನೀವು ದಿನನಿತ್ಯ ಹೇಗೆ ಕಾಣುತ್ತೀರಿ ಎಂಬುದನ್ನೂ ಕುಟುಂಬಗಳು ನೋಡಲು ಬಯಸುತ್ತವೆ."]}, {"p": "ನಿಮಗೆ ಆರಾಮವಾದ ಮತ್ತು ನಿಮ್ಮದೇ ಆದದ್ದನ್ನು ಧರಿಸಿ. ಎರವಲು ಪಡೆದ ರೂಪ ಫೋಟೋದಲ್ಲಿ ಎದ್ದು ಕಾಣುತ್ತದೆ."}]}}$guide$::jsonb, updated_at = now()
 WHERE slug = 'what-to-wear';

UPDATE mangaly_content.guide
   SET content = content || $guide${"mr": {"title": "एखाद्याची तक्रार कशी करावी किंवा त्यांना ब्लॉक कसे करावे", "summary": "काहीही चुकीचे वाटले, तर दोन टॅपमध्ये पाऊल उचलू शकता. हे तुम्ही केले, असे त्यांना कधीही सांगितले जात नाही.", "sections": [{"h": "प्रोफाइलवरून", "points": ["प्रोफाइल उघडा आणि अगदी शेवटपर्यंत खाली जा.", "\"या प्रोफाइलची तक्रार करा किंवा ब्लॉक करा\" वर टॅप करा.", "तक्रार निवडून कारण निवडा, किंवा ब्लॉक निवडा."]}, {"h": "संवादातून", "points": ["संवाद उघडा आणि वरच्या ⋯ मेनूवर टॅप करा.", "तक्रार निवडा. त्या क्षणीचा संवाद तुमच्या तक्रारीसोबत जातो, म्हणजे काय घडले ते आमची सुरक्षा टीम पाहू शकते.", "किंवा ब्लॉक निवडा. संवाद बंद होतो आणि ते तुमच्याशी पुन्हा संपर्क करू शकत नाहीत."]}, {"h": "लगेच तक्रार करा, जर कोणी", "points": ["कोणत्याही कारणाने पैसे, भेटवस्तू किंवा बँकेची माहिती मागत असेल;", "दुसऱ्या ॲपवर जाण्याचा किंवा घाईने एकट्याने भेटण्याचा आग्रह करत असेल;", "आधीच विवाहित असेल, कमी वयाचे असेल, किंवा फोटोतली व्यक्ती ती नसेल."]}, {"p": "ब्लॉक दोन्ही बाजूंनी लागू होतो: Mangalya मध्ये तुम्ही एकमेकांना कुठेही दिसणार नाही."}]}, "kn": {"title": "ಯಾರ ಬಗ್ಗೆಯಾದರೂ ದೂರು ನೀಡುವುದು ಅಥವಾ ಬ್ಲಾಕ್ ಮಾಡುವುದು ಹೇಗೆ", "summary": "ಏನಾದರೂ ಸರಿಯಿಲ್ಲ ಅನ್ನಿಸಿದರೆ, ಎರಡು ಟ್ಯಾಪ್‌ಗಳಲ್ಲಿ ಕ್ರಮ ಕೈಗೊಳ್ಳಬಹುದು. ಇದನ್ನು ನೀವು ಮಾಡಿದ್ದೀರಿ ಎಂದು ಅವರಿಗೆ ಎಂದಿಗೂ ತಿಳಿಸಲಾಗುವುದಿಲ್ಲ.", "sections": [{"h": "ಪ್ರೊಫೈಲ್‌ನಿಂದ", "points": ["ಪ್ರೊಫೈಲ್ ತೆರೆದು ಕೊನೆಯವರೆಗೂ ಕೆಳಗೆ ಹೋಗಿ.", "\"ಈ ಪ್ರೊಫೈಲ್ ಬಗ್ಗೆ ದೂರು ನೀಡಿ ಅಥವಾ ಬ್ಲಾಕ್ ಮಾಡಿ\" ಮೇಲೆ ಟ್ಯಾಪ್ ಮಾಡಿ.", "ದೂರು ಆಯ್ಕೆಮಾಡಿ ಕಾರಣವನ್ನು ಆರಿಸಿ, ಅಥವಾ ಬ್ಲಾಕ್ ಆಯ್ಕೆಮಾಡಿ."]}, {"h": "ಸಂಭಾಷಣೆಯಿಂದ", "points": ["ಸಂಭಾಷಣೆ ತೆರೆದು ಮೇಲಿನ ⋯ ಮೆನುವಿನ ಮೇಲೆ ಟ್ಯಾಪ್ ಮಾಡಿ.", "ದೂರು ಆಯ್ಕೆಮಾಡಿ. ಆ ಕ್ಷಣದ ಸಂಭಾಷಣೆ ನಿಮ್ಮ ದೂರಿನೊಂದಿಗೆ ಹೋಗುತ್ತದೆ, ಇದರಿಂದ ಏನಾಯಿತು ಎಂಬುದನ್ನು ನಮ್ಮ ಸುರಕ್ಷತಾ ತಂಡ ನೋಡಬಹುದು.", "ಅಥವಾ ಬ್ಲಾಕ್ ಆಯ್ಕೆಮಾಡಿ. ಸಂಭಾಷಣೆ ಮುಚ್ಚುತ್ತದೆ ಮತ್ತು ಅವರು ನಿಮ್ಮನ್ನು ಮತ್ತೆ ಸಂಪರ್ಕಿಸಲು ಆಗುವುದಿಲ್ಲ."]}, {"h": "ಯಾರಾದರೂ ಹೀಗೆ ಮಾಡಿದರೆ ತಕ್ಷಣ ದೂರು ನೀಡಿ", "points": ["ಯಾವುದೇ ಕಾರಣಕ್ಕೆ ಹಣ, ಉಡುಗೊರೆ ಅಥವಾ ಬ್ಯಾಂಕ್ ವಿವರಗಳನ್ನು ಕೇಳಿದರೆ;", "ಬೇರೆ ಆ್ಯಪ್‌ಗೆ ಹೋಗಲು ಅಥವಾ ಬೇಗನೆ ಒಬ್ಬರೇ ಭೇಟಿಯಾಗಲು ಒತ್ತಾಯಿಸಿದರೆ;", "ಈಗಾಗಲೇ ಮದುವೆಯಾಗಿದ್ದರೆ, ಅಪ್ರಾಪ್ತರಾಗಿದ್ದರೆ, ಅಥವಾ ಫೋಟೋದಲ್ಲಿರುವ ವ್ಯಕ್ತಿ ಅವರಲ್ಲದಿದ್ದರೆ."]}, {"p": "ಬ್ಲಾಕ್ ಎರಡೂ ಕಡೆಗೆ ಅನ್ವಯಿಸುತ್ತದೆ: Mangalya ಒಳಗೆ ನೀವು ಒಬ್ಬರನ್ನೊಬ್ಬರು ಎಲ್ಲಿಯೂ ನೋಡುವುದಿಲ್ಲ."}]}}$guide$::jsonb, updated_at = now()
 WHERE slug = 'report-or-block';

UPDATE mangaly_content.guide
   SET content = content || $guide${"mr": {"title": "भेटण्यापूर्वी सुरक्षित राहा", "summary": "चांगली कुटुंबे वेळ घेतात. तुम्हीही घेऊ शकता.", "sections": [{"points": ["आधी Mangalya मध्येच बोला. तुम्हाला सहज वाटेल तेव्हाच फोन नंबर द्या; प्रत्येक स्थळाला काय दिसावे ते तुम्ही ठरवता.", "तुम्ही दोघे भेटण्यापूर्वी कुटुंबांना एकमेकांशी बोलू द्या.", "पहिल्यांदा दिवसाउजेडी, वर्दळीच्या सार्वजनिक ठिकाणी भेटा; कुटुंब जवळ असावे किंवा तुम्ही कुठे आहात ते त्यांना माहीत असावे.", "गोष्ट कितीही खरी वाटली तरी कधीही पैसे पाठवू नका. कोणतेही खरे कुटुंब पैसे मागत नाही.", "काहीतरी बरोबर नाही असे वाटले, तर त्या भावनेवर विश्वास ठेवा. कोणतेही कारण न सांगता तुम्ही कधीही मागे हटू शकता."]}]}, "kn": {"title": "ಭೇಟಿಯಾಗುವ ಮೊದಲು ಸುರಕ್ಷಿತವಾಗಿರಿ", "summary": "ಒಳ್ಳೆಯ ಕುಟುಂಬಗಳು ಸಮಯ ತೆಗೆದುಕೊಳ್ಳುತ್ತವೆ. ನೀವೂ ತೆಗೆದುಕೊಳ್ಳಬಹುದು.", "sections": [{"points": ["ಮೊದಲು Mangalya ಒಳಗೇ ಮಾತನಾಡಿ. ನಿಮಗೆ ಸರಿ ಅನ್ನಿಸಿದಾಗ ಮಾತ್ರ ಫೋನ್ ಸಂಖ್ಯೆ ಹಂಚಿಕೊಳ್ಳಿ; ಪ್ರತಿ ಸಂಬಂಧಕ್ಕೆ ಏನು ಕಾಣಬೇಕು ಎಂಬುದನ್ನು ನೀವೇ ನಿರ್ಧರಿಸುತ್ತೀರಿ.", "ನೀವಿಬ್ಬರೂ ಭೇಟಿಯಾಗುವ ಮೊದಲು ಕುಟುಂಬಗಳು ಪರಸ್ಪರ ಮಾತನಾಡಲಿ.", "ಮೊದಲ ಬಾರಿ ಹಗಲು ಹೊತ್ತಿನಲ್ಲಿ, ಜನಸಂಚಾರವಿರುವ ಸಾರ್ವಜನಿಕ ಸ್ಥಳದಲ್ಲಿ ಭೇಟಿಯಾಗಿ; ಕುಟುಂಬದವರು ಹತ್ತಿರದಲ್ಲಿರಲಿ ಅಥವಾ ನೀವು ಎಲ್ಲಿದ್ದೀರಿ ಎಂದು ಅವರಿಗೆ ತಿಳಿದಿರಲಿ.", "ಕಥೆ ಎಷ್ಟೇ ನಿಜವೆನಿಸಿದರೂ ಎಂದಿಗೂ ಹಣ ಕಳುಹಿಸಬೇಡಿ. ಯಾವ ನಿಜವಾದ ಕುಟುಂಬವೂ ಹಣ ಕೇಳುವುದಿಲ್ಲ.", "ಏನೋ ಸರಿಯಿಲ್ಲ ಅನ್ನಿಸಿದರೆ ಆ ಭಾವನೆಯನ್ನು ನಂಬಿ. ಯಾವುದೇ ಕಾರಣ ಹೇಳದೆ ನೀವು ಯಾವಾಗ ಬೇಕಾದರೂ ಹಿಂದೆ ಸರಿಯಬಹುದು."]}]}}$guide$::jsonb, updated_at = now()
 WHERE slug = 'safe-first-meeting';

UPDATE mangaly_content.guide
   SET content = content || $guide${"mr": {"title": "मुलासाठी किंवा मुलीसाठी स्थळ शोधणाऱ्या आई-वडिलांसाठी", "summary": "त्यांच्याकडून निवडीचा हक्क न काढून घेता मदत कशी करावी.", "sections": [{"p": "आज बहुतेक स्थळे आई-वडिलांपासूनच सुरू होतात. टिकतात ती, जी मुलाने किंवा मुलीनेही निवडलेली असतात."}, {"points": ["तुमच्या मुलाच्या किंवा मुलीच्या Home Circle मध्ये सामील व्हा, किंवा त्यांच्यासाठी प्रोफाइल बनवून त्यांना आमंत्रित करा.", "आवडलेली स्थळे जतन करा. तुम्ही जतन केलेली स्थळे तुमच्या मुला-मुलीला दिसतात आणि ते तुमच्याशी त्याबद्दल बोलू शकतात.", "शक्य असेल तिथे विनंती एकत्र मिळून पाठवा. जे स्थळ मुला-मुलीला आधीच आवडले आहे, त्याला जास्त आपुलकीने उत्तर मिळते.", "कुटुंब-संवादात दुसऱ्या आई-वडिलांशी बोला. दोन्ही उमेदवारांचा स्वतःचा संवाद खासगीच राहतो.", "तुम्हाला इंग्रजी वाचता येत नसेल, तर ‘मी’ उघडा, सेटिंग्ज (गिअरचे चिन्ह) वर टॅप करा आणि भाषेमध्ये मराठी निवडा. हे मार्गदर्शनसुद्धा त्याच भाषेत दिसेल."]}]}, "kn": {"title": "ಮಗ ಅಥವಾ ಮಗಳಿಗಾಗಿ ಸಂಬಂಧ ಹುಡುಕುತ್ತಿರುವ ತಂದೆ-ತಾಯಿಗೆ", "summary": "ಅವರಿಂದ ಆಯ್ಕೆಯನ್ನು ಕಸಿದುಕೊಳ್ಳದೆ ಹೇಗೆ ಸಹಾಯ ಮಾಡುವುದು.", "sections": [{"p": "ಇಂದು ಹೆಚ್ಚಿನ ಸಂಬಂಧಗಳು ತಂದೆ-ತಾಯಿಯಿಂದಲೇ ಶುರುವಾಗುತ್ತವೆ. ಉಳಿಯುವುದು ಮಗ ಅಥವಾ ಮಗಳೂ ಆಯ್ಕೆ ಮಾಡಿದ ಸಂಬಂಧಗಳೇ."}, {"points": ["ನಿಮ್ಮ ಮಗ ಅಥವಾ ಮಗಳ Home Circle ಗೆ ಸೇರಿ, ಅಥವಾ ಅವರಿಗಾಗಿ ಪ್ರೊಫೈಲ್ ಮಾಡಿ ಅವರನ್ನು ಆಹ್ವಾನಿಸಿ.", "ಇಷ್ಟವಾದ ಸಂಬಂಧಗಳನ್ನು ಉಳಿಸಿ. ನೀವು ಉಳಿಸಿದವು ನಿಮ್ಮ ಮಗ ಅಥವಾ ಮಗಳಿಗೆ ಕಾಣುತ್ತವೆ, ಮತ್ತು ಅವರು ಅವುಗಳ ಬಗ್ಗೆ ನಿಮ್ಮೊಂದಿಗೆ ಮಾತನಾಡಬಹುದು.", "ಸಾಧ್ಯವಾದಲ್ಲೆಲ್ಲ ವಿನಂತಿಗಳನ್ನು ಜೊತೆಯಾಗಿ ಕಳುಹಿಸಿ. ಮಕ್ಕಳಿಗೆ ಈಗಾಗಲೇ ಇಷ್ಟವಾದ ಸಂಬಂಧಕ್ಕೆ ಹೆಚ್ಚು ಆತ್ಮೀಯ ಉತ್ತರ ಸಿಗುತ್ತದೆ.", "ಕುಟುಂಬ ಸಂಭಾಷಣೆಯಲ್ಲಿ ಇನ್ನೊಂದು ಕಡೆಯ ತಂದೆ-ತಾಯಿಯೊಂದಿಗೆ ಮಾತನಾಡಿ. ಇಬ್ಬರು ಅಭ್ಯರ್ಥಿಗಳ ಸ್ವಂತ ಸಂಭಾಷಣೆ ಖಾಸಗಿಯಾಗಿಯೇ ಇರುತ್ತದೆ.", "ನಿಮಗೆ ಇಂಗ್ಲಿಷ್ ಓದಲು ಬರದಿದ್ದರೆ, ‘ನಾನು’ ತೆರೆಯಿರಿ, ಸೆಟ್ಟಿಂಗ್ಸ್ (ಗೇರ್ ಚಿಹ್ನೆ) ಮೇಲೆ ಟ್ಯಾಪ್ ಮಾಡಿ, ಮತ್ತು ಭಾಷೆಯಲ್ಲಿ ಕನ್ನಡ ಆಯ್ಕೆಮಾಡಿ. ಈ ಮಾರ್ಗದರ್ಶಿಯೂ ಸೇರಿ ಎಲ್ಲವೂ ಅದೇ ಭಾಷೆಗೆ ಬದಲಾಗುತ್ತದೆ."]}]}}$guide$::jsonb, updated_at = now()
 WHERE slug = 'parents-searching';

UPDATE mangaly_content.guide
   SET content = content || $guide${"mr": {"title": "घटस्फोट किंवा जोडीदार गमावल्यानंतर पुन्हा स्थळ शोधताना", "summary": "दुसरे लग्नही पहिल्याइतक्याच सन्मानास पात्र आहे.", "sections": [{"points": ["प्रोफाइलमध्ये स्पष्ट लिहा: घटस्फोटित, घटस्फोटाची प्रक्रिया सुरू आहे, किंवा विधवा/विधुर. जी कुटुंबे उत्तर देतील, ती हे माहीत असूनच देतील.", "मुले असतील तर सांगा, आणि ती तुमच्यासोबत राहतात का तेही. योग्य कुटुंब त्यांच्याबद्दल मायेने विचारेल.", "तुम्ही कोणाला शोधत आहात, हेही तितक्याच काळजीपूर्वक निवडा. अशाच परिस्थितीतले अनेक जणही शोधत आहेत.", "तुम्हाला हवा तेवढा वेळ घ्या. तुमच्या अपेक्षांबाहेरील कोणालाही काहीही दाखवले जात नाही."]}]}, "kn": {"title": "ವಿಚ್ಛೇದನ ಅಥವಾ ಸಂಗಾತಿಯನ್ನು ಕಳೆದುಕೊಂಡ ನಂತರ ಮತ್ತೆ ಹುಡುಕುವಾಗ", "summary": "ಎರಡನೇ ಮದುವೆಯೂ ಮೊದಲನೆಯದಷ್ಟೇ ಗೌರವಕ್ಕೆ ಅರ್ಹ.", "sections": [{"points": ["ಪ್ರೊಫೈಲ್‌ನಲ್ಲಿ ಸ್ಪಷ್ಟವಾಗಿ ಹೇಳಿ: ವಿಚ್ಛೇದಿತ, ವಿಚ್ಛೇದನ ಪ್ರಕ್ರಿಯೆಯಲ್ಲಿ, ಅಥವಾ ವಿಧವೆ/ವಿಧುರ. ಉತ್ತರಿಸುವ ಕುಟುಂಬಗಳು ಇದನ್ನು ತಿಳಿದೇ ಉತ್ತರಿಸುತ್ತವೆ.", "ಮಕ್ಕಳಿದ್ದರೆ ಅದನ್ನು ತಿಳಿಸಿ, ಮತ್ತು ಅವರು ನಿಮ್ಮೊಂದಿಗೆ ಇರುತ್ತಾರೆಯೇ ಎಂಬುದನ್ನೂ. ಸರಿಯಾದ ಕುಟುಂಬ ಅವರ ಬಗ್ಗೆ ಪ್ರೀತಿಯಿಂದ ಕೇಳುತ್ತದೆ.", "ನೀವು ಯಾರನ್ನು ಹುಡುಕುತ್ತಿದ್ದೀರಿ ಎಂಬುದನ್ನೂ ಅಷ್ಟೇ ಕಾಳಜಿಯಿಂದ ಆಯ್ಕೆಮಾಡಿ. ಇದೇ ಪರಿಸ್ಥಿತಿಯಲ್ಲಿರುವ ಅನೇಕರೂ ಹುಡುಕುತ್ತಿದ್ದಾರೆ.", "ನಿಮಗೆ ಬೇಕಾದಷ್ಟು ಸಮಯ ತೆಗೆದುಕೊಳ್ಳಿ. ನಿಮ್ಮ ಆಶಯಗಳ ಹೊರಗಿನ ಯಾರಿಗೂ ಏನನ್ನೂ ತೋರಿಸಲಾಗುವುದಿಲ್ಲ."]}]}}$guide$::jsonb, updated_at = now()
 WHERE slug = 'looking-again';

UPDATE mangaly_content.guide
   SET content = content || $guide${"mr": {"title": "उमेदवार कुटुंबापासून दूर राहत असेल तेव्हा", "summary": "परदेशात किंवा दुसऱ्या शहरात नोकरी, आणि आई-वडील घरी.", "sections": [{"points": ["तुमच्या आई-वडिलांना Home Circle मध्ये जोडा. ते तिथेच कुटुंबांना भेटू शकतात, आणि तुम्ही जिथे आहात तिथूनच बोलू शकता.", "तुम्ही सध्या कुठे राहता ते सांगा, आणि तुम्ही परत याल की जोडीदाराने तुमच्याकडे यावे असे तुम्हाला वाटते, तेही. कुटुंबे सगळ्यात आधी हेच विचारतात.", "तुम्हा दोघांसाठी खासगी संवाद आणि सगळ्यांसाठी कुटुंब-संवाद वापरा, म्हणजे वेगवेगळ्या टाइम झोनमध्येही कोणाला डावलल्यासारखे वाटणार नाही.", "पहिल्या भेटीसाठी, कोणी प्रवास करण्यापूर्वी दोन्ही कुटुंबांसोबत एक व्हिडिओ कॉल ही चांगली सुरुवात आहे."]}]}, "kn": {"title": "ಅಭ್ಯರ್ಥಿ ಕುಟುಂಬದಿಂದ ದೂರ ಇರುವಾಗ", "summary": "ವಿದೇಶದಲ್ಲೋ ಬೇರೆ ಊರಿನಲ್ಲೋ ಕೆಲಸ, ತಂದೆ-ತಾಯಿ ಮನೆಯಲ್ಲಿ.", "sections": [{"points": ["ನಿಮ್ಮ ತಂದೆ-ತಾಯಿಯನ್ನು Home Circle ಗೆ ಸೇರಿಸಿ. ಅವರು ಅಲ್ಲೇ ಕುಟುಂಬಗಳನ್ನು ಭೇಟಿಯಾಗಬಹುದು, ನೀವು ಇರುವಲ್ಲಿಂದಲೇ ಮಾತನಾಡಬಹುದು.", "ನೀವು ಈಗ ಎಲ್ಲಿ ವಾಸಿಸುತ್ತೀರಿ ಎಂದು ತಿಳಿಸಿ, ಮತ್ತು ನೀವು ಹಿಂದಿರುಗುತ್ತೀರೋ ಅಥವಾ ಸಂಗಾತಿ ನಿಮ್ಮ ಬಳಿ ಬರಬೇಕೆಂದು ಬಯಸುತ್ತೀರೋ ಎಂಬುದನ್ನೂ. ಕುಟುಂಬಗಳು ಮೊದಲು ಕೇಳುವುದೇ ಇದನ್ನು.", "ನಿಮ್ಮಿಬ್ಬರಿಗೆ ಖಾಸಗಿ ಸಂಭಾಷಣೆ ಮತ್ತು ಎಲ್ಲರಿಗೂ ಕುಟುಂಬ ಸಂಭಾಷಣೆ ಬಳಸಿ, ಇದರಿಂದ ಬೇರೆ ಬೇರೆ ಸಮಯ ವಲಯಗಳಲ್ಲಿದ್ದರೂ ಯಾರಿಗೂ ಹೊರಗುಳಿದಂತೆ ಅನ್ನಿಸುವುದಿಲ್ಲ.", "ಮೊದಲ ಭೇಟಿಗೆ, ಯಾರಾದರೂ ಪ್ರಯಾಣಿಸುವ ಮೊದಲು ಎರಡೂ ಕುಟುಂಬಗಳು ಇರುವ ಒಂದು ವಿಡಿಯೋ ಕರೆ ಒಳ್ಳೆಯ ಆರಂಭ."]}]}}$guide$::jsonb, updated_at = now()
 WHERE slug = 'families-far-apart';

UPDATE mangaly_content.guide
   SET content = content || $guide${"mr": {"title": "कुटुंबांची पहिली भेट", "summary": "‘बघण्याचा कार्यक्रम’, दोन्ही बाजूंसाठी सोपा.", "sections": [{"h": "आधी", "points": ["कुटुंब-संवादात दिवस, वेळ आणि कोण कोण येणार ते ठरवा. प्रत्येक बाजूने दोन-तीन जण पुरेसे आहेत.", "शांत ठिकाण निवडा: मुलीचे घर, मंदिर, किंवा एखादे शांत कौटुंबिक रेस्टॉरंट. ‘लग्नाची तयारी’ दोन्ही कुटुंबांच्या जवळची ठिकाणे सुचवते.", "तुमच्या कुटुंबासाठी महत्त्वाचे असलेले प्रश्न आधीच विचारून घ्या, म्हणजे भेट मोकळेपणाने होईल."]}, {"h": "त्या दिवशी", "points": ["कुटुंबांच्या नजरेसमोरच, त्या दोघांना थोडा वेळ एकमेकांशी बोलू द्या.", "पैसा, हुंडा आणि मागण्यांचा विषय काढू नका. हुंडा हा कायद्याने गुन्हा आहे आणि Mangalya च्या भावनेच्याही विरुद्ध आहे."]}, {"h": "नंतर", "points": ["प्रत्येक बाजू एक-दोन दिवस विचार करते, मग कुटुंब-संवादात नम्रपणे होकार किंवा नकार कळवते.", "दोघांचा होकार असेल, तर ‘लग्नाची तयारी’ मध्ये टप्पा बदलून ‘सोयरीक पक्की’ करा आणि पुढे काय करायचे ते पाहा."]}]}, "kn": {"title": "ಕುಟುಂಬಗಳ ಮೊದಲ ಭೇಟಿ", "summary": "ಹೆಣ್ಣು ನೋಡುವ ಶಾಸ್ತ್ರ, ಎರಡೂ ಕಡೆಗೆ ಸುಲಭವಾಗಿ.", "sections": [{"h": "ಮೊದಲು", "points": ["ಕುಟುಂಬ ಸಂಭಾಷಣೆಯಲ್ಲಿ ದಿನ, ಸಮಯ ಮತ್ತು ಯಾರು ಯಾರು ಬರುತ್ತಾರೆ ಎಂದು ನಿರ್ಧರಿಸಿ. ಪ್ರತಿ ಕಡೆಯಿಂದ ಇಬ್ಬರು-ಮೂವರು ಸಾಕು.", "ಶಾಂತವಾದ ಸ್ಥಳ ಆಯ್ಕೆಮಾಡಿ: ಹುಡುಗಿಯ ಮನೆ, ದೇವಸ್ಥಾನ, ಅಥವಾ ಶಾಂತವಾದ ಕುಟುಂಬ ರೆಸ್ಟೋರೆಂಟ್. ಎರಡೂ ಕುಟುಂಬಗಳಿಗೆ ಹತ್ತಿರದ ಸ್ಥಳಗಳನ್ನು ‘ಮದುವೆ ಸಿದ್ಧತೆಗಳು’ ಸೂಚಿಸುತ್ತದೆ.", "ನಿಮ್ಮ ಕುಟುಂಬಕ್ಕೆ ಮುಖ್ಯವಾದ ಪ್ರಶ್ನೆಗಳನ್ನು ಮೊದಲೇ ಕೇಳಿಕೊಳ್ಳಿ, ಇದರಿಂದ ಭೇಟಿ ನಿರಾಳವಾಗಿ ನಡೆಯುತ್ತದೆ."]}, {"h": "ಆ ದಿನ", "points": ["ಕುಟುಂಬಗಳ ಕಣ್ಣೆದುರೇ, ಆ ಇಬ್ಬರಿಗೂ ಸ್ವಲ್ಪ ಹೊತ್ತು ತಾವೇ ಮಾತನಾಡಲು ಬಿಡಿ.", "ಹಣ, ವರದಕ್ಷಿಣೆ ಮತ್ತು ಬೇಡಿಕೆಗಳ ಮಾತು ಬೇಡ. ವರದಕ್ಷಿಣೆ ಕಾನೂನಿನ ಪ್ರಕಾರ ಅಪರಾಧ, ಮತ್ತು Mangalya ಆಶಯಕ್ಕೂ ವಿರುದ್ಧ."]}, {"h": "ನಂತರ", "points": ["ಪ್ರತಿ ಕಡೆಯವರು ಒಂದೆರಡು ದಿನ ಯೋಚಿಸಿ, ನಂತರ ಕುಟುಂಬ ಸಂಭಾಷಣೆಯಲ್ಲಿ ವಿನಯದಿಂದ ಹೌದು ಅಥವಾ ಇಲ್ಲ ಎಂದು ತಿಳಿಸುತ್ತಾರೆ.", "ಇಬ್ಬರೂ ಹೌದು ಎಂದರೆ, ‘ಮದುವೆ ಸಿದ್ಧತೆಗಳು’ ಒಳಗೆ ಹಂತವನ್ನು ‘ಕುಟುಂಬಗಳ ಒಪ್ಪಿಗೆ’ ಎಂದು ಬದಲಿಸಿ, ಮುಂದೇನು ಎಂಬುದನ್ನು ನೋಡಿ."]}]}}$guide$::jsonb, updated_at = now()
 WHERE slug = 'the-first-meeting';
